static void stmmac_enable_all_dma_irq ( struct stmmac_priv * priv ) { u32 rx_channels_count = priv -> plat -> rx_queues_to_use ; u32 tx_channels_count = priv -> plat -> tx_queues_to_use ; u32 chan ; for ( chan = 0 ; chan < dma_csr_ch ; chan ++ ) { struct stmmac_channel * ch = & priv -> channel [ chan ] ; unsigned long flags ; spin_lock_irqsave ( & ch -> lock , flags ) ; stmmac_enable_dma_irq ( priv , priv -> ioaddr , chan , 1 , 1 ) ; spin_unlock_irqrestore ( & ch -> lock , flags ) ; } } 